def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    start=None
    for r in range(h):
        for c in range(w):
            if g[r][c]==2: start=(r,c)
    water={start[1]}
    for r in range(start[0],h):
        below=g[r+1] if r+1<h else None
        fill=set(water)
        if below is not None:
            for c in water:
                if below[c]==0: continue
                for d in (-1,1):
                    i=c+d
                    while 0<=i<w and g[r][i]==0:
                        fill.add(i)
                        if below[i]==0: break
                        i+=d
        for c in fill:
            if g[r][c]==0: out[r][c]=2
        if below is None: break
        water={c for c in fill if below[c]==0}
    return out
